SELECT setval('socialapp.q_explanations_id', 301601, FALSE);
SELECT setval('socialapp.q_vault_notes_id',
              GREATEST((SELECT COALESCE(MAX(id), 0) FROM socialapp.t_vault_notes), 1), true);
